// BuildBeacon UI — Saving a file generated by the interface (download).
// Version 1.0 (2026-11-12)

import 'file_save_io.dart'
    if (dart.library.js_interop) 'file_save_web.dart'
    as platform;

/// Saves [text] as the file [name]: a download in the browser. Returns
/// `false` where it is not possible (outside a browser).
typedef SaveTextFile = bool Function(String name, String text, String type);

/// The platform implementation.
const SaveTextFile saveTextFile = platform.saveTextFile;
